var auth=function(n){function t(){n("#resetModal form#form-reset-password").validate({rules:{password:{required:!0,minlength:6},confirmPassword:{required:!0,equalTo:"#password"}},messages:{password:{required:"Hãy nhập mật khẩu",minlength:"Mật khẩu ít nhất 6 kí tự"},confirmPassword:{required:"Hãy xác thực mật khẩu",equalTo:"Xác thực mật khẩu sai"}},submitHandler:function(t){n.ajax({url:"/Auth/ResetPassword",method:"POST",data:n(t).serialize(),success:function(){},error:function(n,t,i){console.log(t+": "+i)}})}})}function i(){n("#resetModal").modal("show");t()}return{init:i}}(jQuery);$(document).ready(function(){auth.init()});